6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;
8	
9	/**
10	 * The duplicate check, rejecting a create-owner request with a {@link DuplicateOwnerException} (409)
11	 * on either of two grounds:
12	 *
13	 * <ul>
14	 * <li><b>Full identity.</b> The whole derived {@link OwnerIdentityKey}
15	 * ({@code telephone|email|householdId}) equals an existing owner's. This always blocks, even when
16	 * the request opts in via {@code sharesHousehold}.</li>
17	 * <li><b>Household.</b> The computed {@code householdId} (see {@link AssignHousehold}, keyed on
18	 * last name and postcode) equals an existing owner's. Because the household is now keyed on
19	 * (last name, postcode), a second owner sharing those is the same household and is blocked — unless
20	 * the request sets {@code sharesHousehold}, which declares the new owner an intentional household
21	 * member and waves this ground through (the full-identity ground still applies).</li>
22	 * </ul>
23	 *
24	 * <p>Runs after {@link BuildOwner} and {@link AssignHousehold} so the new owner's telephone, email
25	 * and {@code householdId} are all in their stored, computed form, and before {@link SaveOwner} so
26	 * the not-yet-persisted new owner is compared only against existing owners.
27	 */
28	public class CheckOwnerIdentityUnique {
29	
30	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
31	            throws DuplicateOwnerException {
32	        String identityKey = OwnerIdentityKey.of(owner);
33	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
34	        String householdId = owner.getHouseholdId();
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
37	                continue; // never a duplicate of itself
38	            }
39	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
40	                throw new DuplicateOwnerException(identityKey);
41	            }
42	            if (!sharesHousehold && householdId != null
43	                    && householdId.equals(existing.getHouseholdId())) {
44	                throw new DuplicateOwnerException("household " + householdId);
45	            }
46	        }
47	    }
48	}
