1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Raises the soft-match {@code possibleDuplicate} flag. A create request that is not a hard
12	 * duplicate (see {@link CheckOwnerIdentityUnique}) can still resemble an existing owner: when it
13	 * shares an existing owner's lastName (compared case-insensitively) and postcode but has a
14	 * <em>different</em> telephone, the new owner is created with {@code possibleDuplicate} true and
15	 * {@code possibleDuplicateOf} set to the matching owner's id. Otherwise {@code possibleDuplicate}
16	 * is false and {@code possibleDuplicateOf} absent.
17	 *
18	 * <p>Now that the household is keyed on (last name, postcode) — see {@link AssignHousehold} — that
19	 * soft-match key <em>is</em> the household key: a same lastName+postcode owner is only ever created
20	 * here as a <b>declared household member</b> (it reached this step because it set
21	 * {@code sharesHousehold}; without it {@link CheckOwnerIdentityUnique} would have rejected it as a
22	 * 409 household duplicate). A declared member is not a suspected duplicate, so an opted-in request
23	 * is never flagged.
24	 *
25	 * <p>Runs after {@link BuildOwner} (telephone, lastName and postcode are in their stored form) and
26	 * after {@link CheckOwnerIdentityUnique}, and before {@link SaveOwner} so the flag is compared only
27	 * against existing owners. When several existing owners match, the one with the lowest id wins for a
28	 * deterministic result.
29	 */
30	public class AssignPossibleDuplicate {
31	
32	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
33	        owner.setPossibleDuplicate(false);
34	        owner.setPossibleDuplicateOf(null);
35	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
36	            return; // a declared household member is not a suspected duplicate
37	        }
38	        String lastName = normalize(owner.getLastName());
